import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

// spec: specs/hal-engine-config-hooks/spec.md#8
it('preserves string, object and undefined rejection causes for onError', async () => {
  const outcomes = [];
  for (const reason of ['string boom', {code: 503}, undefined]) {
    const errors: Error[] = [];
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const orchestrator = createChatOrchestrator(
      createMockProvider(),
      new PromptBuilder({identity: 'Test assistant'}),
      undefined,
      {
        hooks: {
          beforeSession: async () => {
            throw reason;
          },
          onError: async (_session, error) => {
            errors.push(error);
          },
        },
      }
    );
    const rejection = await orchestrator.processMessage(session).then(
      () => ({rejected: false, reason: undefined}),
      (reason: unknown) => ({rejected: true, reason})
    );
    outcomes.push({
      calls: errors.length,
      isError: errors[0] instanceof Error,
      cause: errors[0]?.cause === reason && Object.hasOwn(errors[0] ?? {}, 'cause'),
      readable: Boolean(errors[0]?.message),
      unchanged: rejection.rejected && rejection.reason === reason,
    });
  }
  expect(outcomes).toEqual(
    Array(3).fill({calls: 1, isError: true, cause: true, readable: true, unchanged: true})
  );
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/onErrorCause.test.ts --runInBand"
